  <title>Image Preview</title>
  <style>
    :root {
      color-scheme: light;
      --bg: #f4f7fb;
      --surface: #ffffff;
      --surface-strong: #f8fafc;
      --text: #172033;
      --muted: #5f6c84;
      --border: #d5deea;
      --shadow: 0 24px 60px rgba(15, 23, 42, 0.16);
      --primary: #2563eb;
      --primary-strong: #1d4ed8;
      --danger: #c62828;
      --danger-strong: #a61f1f;
      --danger-soft: #fff1f1;
      --success: #166534;
      --focus: #0f62fe;
      --radius-lg: 24px;
      --radius-md: 16px;
      --radius-sm: 12px;
    }

    * {
      box-sizing: border-box;
    }

    html,
    body {
      margin: 0;
      min-height: 100%;
      font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
      background:
        radial-gradient(circle at top, rgba(37, 99, 235, 0.12), transparent 30%),
        linear-gradient(180deg, #f8fbff 0%, var(--bg) 100%);
      color: var(--text);
    }

    body {
      min-width: 320px;
    }

    a,
    button {
      font: inherit;
    }

    button {
      border: 0;
      cursor: pointer;
    }

    button:focus-visible,
    a:focus-visible {
      outline: 3px solid var(--focus);
      outline-offset: 3px;
    }

    img {
      display: block;
      max-width: 100%;
      height: auto;
    }

    .skip-link {
      position: absolute;
      left: 1rem;
      top: 1rem;
      transform: translateY(-200%);
      padding: 0.75rem 1rem;
      border-radius: 999px;
      background: var(--text);
      color: #fff;
      text-decoration: none;
      z-index: 20;
    }

    .skip-link:focus {
      transform: translateY(0);
    }

    .page-shell {
      display: flex;
      align-items: center;
      justify-content: center;
      padding: 2rem 1rem;
    }

    .app-frame {
      width: min(100%, 1100px);
      display: grid;
      gap: 1.5rem;
    }

    .hero {
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
      padding: 1.5rem;
      border: 1px solid rgba(255, 255, 255, 0.7);
      border-radius: var(--radius-lg);
      background: rgba(255, 255, 255, 0.72);
      backdrop-filter: blur(14px);
      box-shadow: var(--shadow);
    }

    .eyebrow {
      margin: 0 0 0.5rem;
      font-size: 0.85rem;
      font-weight: 700;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      color: var(--primary);
    }

    h1 {
      margin: 0;
      font-size: clamp(2rem, 4vw, 3.25rem);
      line-height: 1.05;
    }

    .hero p,
    .meta-copy,
    .status-message,
    .dialog-copy {
      color: var(--muted);
      line-height: 1.6;
    }

    .hero p,
    .meta-copy,
    .dialog-copy {
      margin: 0;
      max-width: 62ch;
    }

    .hero-stat {
      min-width: 180px;
      padding: 1rem 1.125rem;
      border-radius: var(--radius-md);
      background: linear-gradient(180deg, #f8fbff 0%, #eef4ff 100%);
      border: 1px solid #d9e6ff;
    }

    .hero-stat strong,
    .hero-stat span {
      display: block;
    }

    .hero-stat strong {
      font-size: 1.6rem;
    }

    .content-grid {
      display: grid;
      gap: 1.5rem;
      grid-template-columns: minmax(0, 1.65fr) minmax(280px, 0.95fr);
    }

    .panel,
    .sidebar-card {
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: var(--radius-lg);
      box-shadow: var(--shadow);
    }

    .preview-card {
      padding: 1.25rem;
    }

    .preview-image-wrap {
      overflow: hidden;
      border-radius: 20px;
      background:
        linear-gradient(180deg, rgba(255, 255, 255, 0) 0%, rgba(23, 32, 51, 0.1) 100%),
        #dbe9ff;
    }

    .preview-image {
      aspect-ratio: 16 / 10;
      width: 100%;
      object-fit: cover;
    }

    .preview-footer {
      display: flex;
      flex-wrap: wrap;
      align-items: flex-start;
      justify-content: space-between;
      gap: 1rem;
      padding-top: 1rem;
    }

    .preview-footer h2 {
      margin: 0 0 0.5rem;
      font-size: 1.3rem;
    }

    .meta-list {
      display: flex;
      flex-wrap: wrap;
      gap: 0.75rem;
      margin: 1rem 0 0;
      padding: 0;
      list-style: none;
    }

    .meta-list li {
      padding: 0.55rem 0.8rem;
      border-radius: 999px;
      background: var(--surface-strong);
      color: var(--muted);
      font-size: 0.95rem;
    }

    .action-stack {
      display: grid;
      gap: 0.75rem;
      min-width: min(100%, 240px);
    }

    .button {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 0.5rem;
      min-height: 48px;
      padding: 0.875rem 1rem;
      border-radius: 999px;
      font-weight: 700;
      transition: transform 0.15s ease, background-color 0.15s ease;
    }

    .button:hover {
      transform: translateY(-1px);
    }

    .button-primary {
      background: var(--primary);
      color: #fff;
    }

    .button-primary:hover {
      background: var(--primary-strong);
    }

    .button-secondary {
      background: #eef4ff;
      color: var(--primary-strong);
    }

    .button-secondary:hover {
      background: #dfeaff;
    }

    .button-danger {
      background: var(--danger-soft);
      color: var(--danger);
      border: 1px solid #f1c4c4;
    }

    .button-danger:hover {
      background: #ffe1e1;
      color: var(--danger-strong);
    }

    .sidebar-card {
      padding: 1.25rem;
    }

    .sidebar-card h2 {
      margin: 0 0 0.5rem;
      font-size: 1.15rem;
    }

    .sidebar-list {
      margin: 1rem 0 0;
      padding: 0;
      list-style: none;
      display: grid;
      gap: 0.9rem;
    }

    .sidebar-list li {
      padding: 0.95rem 1rem;
      border-radius: var(--radius-md);
      background: var(--surface-strong);
      color: var(--muted);
    }

    .sidebar-list strong {
      display: block;
      margin-bottom: 0.25rem;
      color: var(--text);
    }

    .status-message {
      margin-top: 1rem;
      min-height: 1.5rem;
      font-weight: 600;
      color: var(--success);
    }

    dialog {
      width: min(100%, 460px);
      padding: 0;
      border: 1px solid var(--border);
      border-radius: 28px;
      background: var(--surface);
      box-shadow: 0 32px 80px rgba(15, 23, 42, 0.3);
    }

    dialog::backdrop {
      background: rgba(15, 23, 42, 0.55);
      backdrop-filter: blur(4px);
    }

    .dialog-panel {
      padding: 1.5rem;
    }

    .dialog-header {
      display: flex;
      align-items: flex-start;
      justify-content: space-between;
      gap: 1rem;
      margin-bottom: 1rem;
    }

    .dialog-header h2 {
      margin: 0;
      font-size: 1.35rem;
    }

    .dialog-close {
      width: 2.5rem;
      height: 2.5rem;
      border-radius: 999px;
      background: #eef2f7;
      color: var(--text);
      flex: 0 0 auto;
    }

    .dialog-actions {
      display: flex;
      flex-wrap: wrap;
      justify-content: flex-end;
      gap: 0.75rem;
      margin-top: 1.5rem;
    }

    .deleted-state {
      opacity: 0.7;
    }

    .deleted-state .preview-image {
      filter: grayscale(1);
    }

    .deleted-badge {
      display: inline-flex;
      align-items: center;
      padding: 0.45rem 0.7rem;
      border-radius: 999px;
      background: #ecfdf3;
      color: var(--success);
      font-weight: 700;
    }

    @media (max-width: 820px) {
      .content-grid {
        grid-template-columns: 1fr;
      }
    }

    @media (forced-colors: active) {
      :root {
        --bg: Canvas;
        --surface: Canvas;
        --surface-strong: Canvas;
        --text: CanvasText;
        --muted: CanvasText;
        --border: ButtonBorder;
        --primary: Highlight;
        --primary-strong: Highlight;
        --danger: CanvasText;
        --danger-strong: CanvasText;
        --danger-soft: Canvas;
        --success: CanvasText;
        --focus: Highlight;
      }

      .hero,
      .panel,
      .sidebar-card,
      dialog,
      .hero-stat,
      .meta-list li,
      .sidebar-list li,
      .dialog-close {
        border: 1px solid ButtonBorder;
        box-shadow: none;
      }

      .button {
        border: 1px solid ButtonBorder;
      }
    }
  </style>
</head>
<body>
  <div id="app"></div>
  <script>
    const imageData = {
      title: "Golden Hour Balcony",
      photographer: "Maya Chen",
      resolution: "6016 x 4016",
      format: "JPG",
      collection: "Summer Campaign",
      size: "8.4 MB",
      imageUrl: "https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1200&q=80"
    };

    const Header = () => `
      <header class="hero">
        <div>
          <p class="eyebrow">Library preview</p>
          <h1>Review image details before you remove it</h1>
          <p>Inspect the current asset, double-check where it is being used, and confirm deletion only when you are ready to remove it from your library.</p>
        </div>
        <div class="hero-stat" aria-label="Images in library">
          <span>Active assets</span>
          <strong>128</strong>
          <span>Across 14 collections</span>
        </div>
      </header>
    `;

    const ImagePreviewCard = () => `
      <section class="panel preview-card" aria-labelledby="image-preview-title">
        <div id="image-card">
          <div class="preview-image-wrap">
            <img
              class="preview-image"
              src="${imageData.imageUrl}"
              alt="Sunlit balcony with plants and a city view during golden hour."
            >
          </div>
          <div class="preview-footer">
            <div>
              <h2 id="image-preview-title">${imageData.title}</h2>
              <p class="meta-copy">Shot by ${imageData.photographer}. This hero image is currently available in your shared media library.</p>
              <ul class="meta-list" aria-label="Image metadata">
                <li>${imageData.resolution}</li>
                <li>${imageData.format}</li>
                <li>${imageData.size}</li>
              </ul>
            </div>
            <div class="action-stack">
              <button type="button" class="button button-secondary">Download original</button>
              <button type="button" class="button button-danger trigger" id="open-delete-dialog">
                Delete image
              </button>
            </div>
          </div>
          <p id="status-message" class="status-message" aria-live="polite"></p>
        </div>
      </section>
    `;

    const UsagePanel = () => `
      <aside class="sidebar-card" aria-labelledby="usage-panel-title">
        <h2 id="usage-panel-title">Usage snapshot</h2>
        <p class="meta-copy">Review where this file appears before removing it from your team library.</p>
        <ul class="sidebar-list">
          <li>
            <strong>Collection</strong>
            ${imageData.collection}
          </li>
          <li>
            <strong>Last edited</strong>
            Today by ${imageData.photographer}
          </li>
          <li>
            <strong>Referenced in</strong>
            Homepage hero, social launch deck, email banner
          </li>
        </ul>
      </aside>
    `;

    const DeleteDialog = () => `
      <dialog id="delete-dialog" aria-labelledby="delete-dialog-title" aria-describedby="delete-dialog-description">
        <form method="dialog" class="dialog-panel">
          <div class="dialog-header">
            <div>
              <h2 id="delete-dialog-title">Delete this image?</h2>
              <p id="delete-dialog-description" class="dialog-copy">This will remove <strong>${imageData.title}</strong> from your library. Any places that still reference the file will need a replacement image.</p>
            </div>
            <button type="submit" class="dialog-close" aria-label="Close confirmation dialog">X</button>
          </div>
          <div class="dialog-actions">
            <button type="submit" class="button button-secondary" value="cancel">Keep image</button>
            <button type="button" class="button button-danger" id="confirm-delete">Yes, delete image</button>
          </div>
        </form>
      </dialog>
    `;

    const App = () => `
      <a class="skip-link" href="#main-content">Skip to main content</a>
      <div class="page-shell">
        <main id="main-content" class="app-frame">
          ${Header()}
          <section class="content-grid">
            ${ImagePreviewCard()}
            ${UsagePanel()}
          </section>
        </main>
      </div>
      ${DeleteDialog()}
    `;

    const appRoot = document.getElementById("app");
    appRoot.innerHTML = App();

    const dialog = document.getElementById("delete-dialog");
    const openDialogButton = document.getElementById("open-delete-dialog");
    const confirmDeleteButton = document.getElementById("confirm-delete");
    const imageCard = document.getElementById("image-card");
    const statusMessage = document.getElementById("status-message");

    openDialogButton.addEventListener("click", () => {
      dialog.showModal();
      confirmDeleteButton.focus();
    });

    dialog.addEventListener("click", (event) => {
      const bounds = dialog.getBoundingClientRect();
      const isBackdropClick =
        event.clientX < bounds.left ||
        event.clientX > bounds.right ||
        event.clientY < bounds.top ||
        event.clientY > bounds.bottom;

      if (isBackdropClick) {
        dialog.close("cancel");
      }
    });

    confirmDeleteButton.addEventListener("click", () => {
      imageCard.classList.add("deleted-state");
      openDialogButton.disabled = true;
      openDialogButton.textContent = "Image deleted";
      statusMessage.innerHTML = '<span class="deleted-badge">Image removed from library</span>';
      dialog.close("deleted");
    });
  </script>
</body>
</html>
